import React, { useState, useEffect } from 'react';
import { useNavigate } from "react-router-dom";
import './supplier.css';

function Suppliers({ deleteSupplier }) {

  // Define navigate
  const navigate = useNavigate();

  let [search, setSearch] = useState("")
  let [sort, setSort] = useState("name")
  let [suppliers, setSuppliers] = useState([])

  

  // State for modal vivibility and selected supplie
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState(null);


  async function getSuppliers() {
    try {
      const response = await fetch("http://localhost:8080/suppliers")
      if (!response.ok) {
        throw new Error("Supplier not found");
      }
      const data = await response.json();
      return data;
      } catch (error) {
        console.error(error);
        alert("Could not fetch supplier: " + error.message);
        return[];
    }   
  }

  function onSearchChange(e) {
    setSearch(e.target.value)
  }

  function onSortChange(e) {
    setSort(e.target.value)
  }

  function getSortedSuppliersData() {
    return suppliers
      .filter((item) => {
        const searchTerm = search.toLowerCase();
        return (
          item.name.toLowerCase().includes(searchTerm) ||
          item.contact.toLowerCase().includes(searchTerm) ||
          item.phone.toLowerCase().includes(searchTerm) ||
          item.email.toLowerCase().includes(searchTerm) ||
          item.website.toLowerCase().includes(searchTerm)
        );
      })
      .sort((a, b) => {
        return (a[sort] + "").localeCompare(b[sort] + "");
      });
  }

  useEffect(() => {
    getSuppliers().then(setSuppliers);
  }, []); // Get the new list if it is any changes

  
   // Function when someone click on the delete-button
   const handleDelete = (id) => {
    deleteSupplier(id);
    setSuppliers((prev) => prev.filter(supplier => supplier.id !== id));  // Uppdate the local list
  };

  // Confirm deletion 
  const confirmDelete = () => {
    deleteSupplier(supplierToDelete);
    setIsModalOpen(false); // Blose the modal after deletion
  };

  // Cancel deletion
  const cancelDelete = () => {
    setIsModalOpen(false); // Close the modal without deleting 
  } 
  


  return (
    <>

      <h1>Suppliers</h1>


      <div className="tableFunctions">
        <div className="tableSeachbar">
          <i class="bi bi-search"></i>
          <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
        </div>

        <div className='sortWithAddFunctions'>
          <select className="tableSort" onChange={onSortChange} value={sort}>
            <option selected value="id">
              Product ID
              <i className='bi bi-chevron-down'></i>
            </option>
            <option value="name">Name</option>
            <option value="contact">Contact Pers.</option>
          </select>

          <button className="addBtn" onClick={() => window.location.href = "/suppliers/add-supplier"}>
            Add Supplier
          </button>
        </div>
      </div>

      <div className="table-container">
        <table>
          <thead>
            <tr>
              <th>Supplier ID</th>
              <th>Name</th>
              <th>Contact person</th>
              <th>Phone number</th>
              <th>Email</th>
              <th>Website</th>
              <th>Edit</th>
              <th>Delete</th>
            </tr>
          </thead>

          <tbody>
            { suppliers.length > 0 &&
              getSortedSuppliersData().map((item) => {
                return <tr key ={item.supplierID}>
                  <td>{item.supplierID}</td>
                  <td><a href={'/suppliers/info/' + item.supplierID}>{item.name}</a></td>
                  <td>{item.contact}</td>
                  <td>{item.phone}</td>
                  <td>{item.email}</td>
                  <td>{item.website}</td>
                  <td>
                    {/*Edit button for supplier */}
                    <button className="editBtn" onClick={() => navigate(`/suppliers/edit/${item.supplierID}`)}>
                      <i className="bi bi-pencil-square"></i>
                    </button>
                  </td>
                  <td>
                    {/*Delete button for supplier  */}
                    <button className="deleteBtn" onClick={() => handleDelete(item.supplierID)}>
                      <i className="bi bi-trash"></i>
                    </button>
                  </td>
                  
                </tr>
              })
            }
          </tbody>
        </table>
      </div>
      
      {/*Modal for confirmation */}
      {isModalOpen && ( 
        <div className="modal">
          <div className="modal-content">
            <h3>Are you sure you want to delete this supplier?</h3>
            <div className="modal-buttons">
              <button className="modal-btn" onClick={confirmDelete}>
                Yes
              </button>
              <button className="modal-btn" onClick={cancelDelete}>
                Cancel
              </button>
            </div>
          </div>
        </div> 
        
      )}

    </>
  )
}

export default Suppliers;
